// clients/core — peer-assisted delivery for public media.
//
// The server only provides public-file eligibility, short-lived peer discovery and opaque signaling.
// Payload bytes flow over WebRTC DataChannel (DTLS encrypted), are split into bounded chunks and are
// accepted only after the receiver recomputes the server-owned SHA-256. Every failure returns null so
// MediaCache can immediately fall back to the ordinary authenticated file endpoint.
import { ApiError, NetworkError } from "./errors.ts";
import type { TokenStore } from "./api.ts";

export interface PeerFetchedBlob {
  fileId: number;
  bytes: Uint8Array;
  mime: string;
  sha256: string;
}

export interface PeerLocalBlob {
  bytes: Uint8Array;
  mime: string;
}

export interface PeerLookup {
  file_id: number;
  sha256: string;
  mime: string;
  size: number;
  providers: string[];
}

export interface PeerSignalEnvelope {
  from_peer_id: string;
  session_id: string;
  payload: unknown;
}

export interface PeerSignaling {
  announce(peerId: string, fileIds: number[], signal?: AbortSignal): Promise<number[]>;
  lookup(peerId: string, fileId: number, signal?: AbortSignal): Promise<PeerLookup>;
  signal(fromPeerId: string, toPeerId: string, sessionId: string, payload: unknown, signal?: AbortSignal): Promise<void>;
  poll(peerId: string, signal?: AbortSignal): Promise<PeerSignalEnvelope[]>;
}

export interface HttpPeerSignalingOptions {
  baseUrl: string;
  tokens: TokenStore;
  clientId: string;
  refresh?: () => Promise<boolean>;
  fetchImpl?: typeof fetch;
}

type WireEnvelope<T> = { ok?: boolean; result?: T; error?: { code?: string; message?: string } };

export class HttpPeerSignaling implements PeerSignaling {
  private readonly baseUrl: string;
  private readonly tokens: TokenStore;
  private readonly clientId: string;
  private readonly refresh: (() => Promise<boolean>) | undefined;
  private readonly fetchImpl: typeof fetch;

  constructor(opts: HttpPeerSignalingOptions) {
    this.baseUrl = opts.baseUrl.replace(/\/+$/, "");
    this.tokens = opts.tokens;
    this.clientId = opts.clientId;
    this.refresh = opts.refresh;
    this.fetchImpl = opts.fetchImpl ?? globalThis.fetch.bind(globalThis);
  }

  announce(peerId: string, fileIds: number[], signal?: AbortSignal): Promise<number[]> {
    return this.post<{ accepted_file_ids?: unknown }>("/v1/files/peer/announce", {
      peer_id: peerId,
      file_ids: fileIds.slice(0, 128),
    }, signal).then((result) => Array.isArray(result.accepted_file_ids)
      ? result.accepted_file_ids.filter((v): v is number => Number.isSafeInteger(v) && Number(v) > 0)
      : []);
  }

  lookup(peerId: string, fileId: number, signal?: AbortSignal): Promise<PeerLookup> {
    return this.post<PeerLookup>("/v1/files/peer/lookup", { peer_id: peerId, file_id: fileId }, signal);
  }

  async signal(
    fromPeerId: string,
    toPeerId: string,
    sessionId: string,
    payload: unknown,
    signal?: AbortSignal,
  ): Promise<void> {
    await this.post("/v1/files/peer/signal", {
      from_peer_id: fromPeerId,
      to_peer_id: toPeerId,
      session_id: sessionId,
      payload,
    }, signal);
  }

  poll(peerId: string, signal?: AbortSignal): Promise<PeerSignalEnvelope[]> {
    return this.post<{ signals?: unknown }>("/v1/files/peer/poll", { peer_id: peerId }, signal)
      .then((result) => Array.isArray(result.signals)
        ? result.signals.filter(isPeerSignalEnvelope)
        : []);
  }

  private async post<T = Record<string, unknown>>(
    pathname: string,
    body: Record<string, unknown>,
    signal?: AbortSignal,
  ): Promise<T> {
    let refreshed = false;
    for (;;) {
      const headers: Record<string, string> = {
        "content-type": "application/json",
        "x-gc-client": this.clientId,
      };
      if (this.tokens.access) headers.authorization = `Bearer ${this.tokens.access}`;
      let response: Response;
      try {
        response = await this.fetchImpl(`${this.baseUrl}${pathname}`, {
          method: "POST",
          headers,
          body: JSON.stringify(body),
          ...(signal ? { signal } : {}),
        });
      } catch (error) {
        if (signal?.aborted) throw error;
        throw new NetworkError("peer signaling network failure", error);
      }
      const text = await response.text();
      let parsed: WireEnvelope<T>;
      try { parsed = text ? JSON.parse(text) as WireEnvelope<T> : {}; }
      catch { throw new ApiError("BAD_RESPONSE", `peer signaling returned non-JSON (HTTP ${response.status})`, response.status); }
      if (parsed.ok === true && parsed.result !== undefined) return parsed.result;
      if (response.status === 401 && this.refresh && !refreshed) {
        refreshed = true;
        if (await this.refresh()) continue;
      }
      throw new ApiError(
        parsed.error?.code ?? "BAD_RESPONSE",
        parsed.error?.message ?? `peer signaling failed (HTTP ${response.status})`,
        response.status,
      );
    }
  }
}

function isPeerSignalEnvelope(value: unknown): value is PeerSignalEnvelope {
  if (!value || typeof value !== "object") return false;
  const row = value as Partial<PeerSignalEnvelope>;
  return typeof row.from_peer_id === "string" && typeof row.session_id === "string" && "payload" in row;
}

type SignalPayload =
  | { type: "offer"; file_id: number; sha256: string; sdp: RTCSessionDescriptionInit }
  | { type: "answer"; sdp: RTCSessionDescriptionInit }
  | { type: "ice"; candidate: RTCIceCandidateInit }
  | { type: "cancel" };

type PeerMetaFrame = {
  type: "meta";
  file_id: number;
  sha256: string;
  mime: string;
  size: number;
};

type PeerDoneFrame = { type: "done" };

type ActiveRtc = {
  pc: RTCPeerConnection;
  remotePeerId: string;
  pendingIce: RTCIceCandidateInit[];
  expiresAt: number;
};

export interface WebRtcPeerDeliveryOptions {
  signaling: PeerSignaling;
  readLocal(fileId: number): Promise<PeerLocalBlob | null>;
  peerId?: string;
  rtcFactory?: (config: RTCConfiguration) => RTCPeerConnection;
  rtcConfig?: RTCConfiguration;
  cryptoImpl?: Crypto;
  now?: () => number;
  pollIntervalMs?: number;
  requestTimeoutMs?: number;
  chunkBytes?: number;
}

const DEFAULT_RTC_CONFIG: RTCConfiguration = {
  // STUN only discovers paths; GreenChat's deployment can inject its existing TURN list here.
  iceServers: [{ urls: "stun:stun.l.google.com:19302" }],
};
const DEFAULT_POLL_MS = 650;
const DEFAULT_REQUEST_TIMEOUT_MS = 4_500;
const DEFAULT_CHUNK_BYTES = 64 * 1024;
const MAX_BUFFERED_BYTES = 1024 * 1024;

export class WebRtcPeerDelivery {
  readonly peerId: string;
  private readonly signaling: PeerSignaling;
  private readonly readLocal: (fileId: number) => Promise<PeerLocalBlob | null>;
  private readonly rtcFactory: ((config: RTCConfiguration) => RTCPeerConnection) | undefined;
  private rtcConfig: RTCConfiguration;
  private readonly cryptoImpl: Crypto;
  private readonly now: () => number;
  private readonly pollIntervalMs: number;
  private readonly requestTimeoutMs: number;
  private readonly chunkBytes: number;
  private readonly active = new Map<string, ActiveRtc>();
  private readonly announced = new Set<number>();
  private pollTimer: ReturnType<typeof setTimeout> | null = null;
  private polling = false;
  private stopped = false;
  private pollEpoch = 0;

  constructor(opts: WebRtcPeerDeliveryOptions) {
    this.signaling = opts.signaling;
    this.readLocal = opts.readLocal;
    this.cryptoImpl = opts.cryptoImpl ?? globalThis.crypto;
    this.peerId = opts.peerId ?? this.cryptoImpl.randomUUID();
    this.rtcFactory = opts.rtcFactory ?? (typeof RTCPeerConnection === "undefined"
      ? undefined
      : (config) => new RTCPeerConnection(config));
    this.rtcConfig = opts.rtcConfig ?? DEFAULT_RTC_CONFIG;
    this.now = opts.now ?? Date.now;
    this.pollIntervalMs = opts.pollIntervalMs ?? DEFAULT_POLL_MS;
    this.requestTimeoutMs = opts.requestTimeoutMs ?? DEFAULT_REQUEST_TIMEOUT_MS;
    this.chunkBytes = Math.max(16 * 1024, Math.min(256 * 1024, opts.chunkBytes ?? DEFAULT_CHUNK_BYTES));
  }

  start(): void {
    if (this.stopped || this.pollTimer || this.polling || !this.rtcFactory) return;
    this.schedulePoll(0, this.pollEpoch);
  }

  setRtcConfig(config: RTCConfiguration): void {
    this.rtcConfig = config;
  }

  stop(): void {
    this.stopped = true;
    this.pollEpoch += 1;
    if (this.pollTimer) clearTimeout(this.pollTimer);
    this.pollTimer = null;
    for (const session of this.active.values()) session.pc.close();
    this.active.clear();
    this.announced.clear();
  }

  reset(): void {
    this.pollEpoch += 1;
    if (this.pollTimer) clearTimeout(this.pollTimer);
    this.pollTimer = null;
    this.polling = false;
    for (const session of this.active.values()) session.pc.close();
    this.active.clear();
    this.announced.clear();
  }

  async announce(fileIds: number[]): Promise<void> {
    if (!this.rtcFactory || this.stopped) return;
    const candidates = [...new Set(fileIds.filter((id) => Number.isSafeInteger(id) && id > 0))]
      .filter((id) => !this.announced.has(id));
    if (!candidates.length) return;
    this.start();
    const accepted = await this.signaling.announce(this.peerId, candidates).catch(() => []);
    for (const id of accepted) this.announced.add(id);
  }

  async fetch(fileId: number, signal?: AbortSignal): Promise<PeerFetchedBlob | null> {
    if (!this.rtcFactory || this.stopped || signal?.aborted) return null;
    this.start();
    let lookup: PeerLookup;
    try { lookup = await this.signaling.lookup(this.peerId, fileId, signal); }
    catch { return null; }
    if (!validLookup(lookup) || lookup.providers.length === 0) return null;
    for (const provider of lookup.providers.slice(0, 3)) {
      if (signal?.aborted) return null;
      try {
        const blob = await this.fetchFromProvider(provider, lookup, signal);
        if (blob) {
          this.announced.add(fileId);
          void this.signaling.announce(this.peerId, [...this.announced].slice(-128)).catch(() => undefined);
          return blob;
        }
      } catch {
        // A peer disappearing, failing integrity, or being behind an incompatible NAT is expected.
      }
    }
    return null;
  }

  private async fetchFromProvider(
    provider: string,
    lookup: PeerLookup,
    outerSignal?: AbortSignal,
  ): Promise<PeerFetchedBlob | null> {
    const pc = this.rtcFactory!(this.rtcConfig);
    const sessionId = this.cryptoImpl.randomUUID();
    const session: ActiveRtc = {
      pc,
      remotePeerId: provider,
      pendingIce: [],
      expiresAt: this.now() + this.requestTimeoutMs + 2_000,
    };
    this.active.set(sessionId, session);
    this.installIceRelay(sessionId, session);
    const channel = pc.createDataChannel("gc-public-media", { ordered: true });
    const received = receiveVerifiedBlob(channel, lookup, this.cryptoImpl, outerSignal);
    try {
      const offer = await pc.createOffer();
      await pc.setLocalDescription(offer);
      await this.signaling.signal(this.peerId, provider, sessionId, {
        type: "offer",
        file_id: lookup.file_id,
        sha256: lookup.sha256,
        sdp: pc.localDescription ?? offer,
      } satisfies SignalPayload, outerSignal);
      return await withTimeout(received, this.requestTimeoutMs, outerSignal);
    } finally {
      this.active.delete(sessionId);
      pc.close();
    }
  }

  private installIceRelay(sessionId: string, session: ActiveRtc): void {
    session.pc.addEventListener("icecandidate", (event) => {
      if (!event.candidate) return;
      void this.signaling.signal(
        this.peerId,
        session.remotePeerId,
        sessionId,
        { type: "ice", candidate: event.candidate.toJSON() } satisfies SignalPayload,
      ).catch(() => undefined);
    });
  }

  private schedulePoll(delay: number, epoch: number): void {
    if (this.stopped || epoch !== this.pollEpoch) return;
    this.pollTimer = setTimeout(() => {
      this.pollTimer = null;
      void this.pollOnce(epoch);
    }, delay);
  }

  private async pollOnce(epoch: number): Promise<void> {
    if (this.stopped || epoch !== this.pollEpoch || this.polling || !this.rtcFactory) return;
    this.polling = true;
    try {
      const signals = await this.signaling.poll(this.peerId).catch(() => []);
      if (epoch !== this.pollEpoch) return;
      for (const envelope of signals) await this.handleSignal(envelope).catch(() => undefined);
      this.pruneActive();
    } finally {
      this.polling = false;
      this.schedulePoll(this.pollIntervalMs, epoch);
    }
  }

  private async handleSignal(envelope: PeerSignalEnvelope): Promise<void> {
    const payload = parseSignalPayload(envelope.payload);
    if (!payload) return;
    if (payload.type === "offer") {
      await this.acceptOffer(envelope.from_peer_id, envelope.session_id, payload);
      return;
    }
    const session = this.active.get(envelope.session_id);
    if (!session || session.remotePeerId !== envelope.from_peer_id) return;
    if (payload.type === "answer") {
      await session.pc.setRemoteDescription(payload.sdp);
      await this.flushIce(session);
    } else if (payload.type === "ice") {
      if (session.pc.remoteDescription) await session.pc.addIceCandidate(payload.candidate);
      else session.pendingIce.push(payload.candidate);
    } else if (payload.type === "cancel") {
      session.pc.close();
      this.active.delete(envelope.session_id);
    }
  }

  private async acceptOffer(remotePeerId: string, sessionId: string, offer: Extract<SignalPayload, { type: "offer" }>): Promise<void> {
    if (this.active.has(sessionId)) return;
    // A remote peer may request only a file this device successfully announced through the server.
    // This is the provider-side privacy boundary: opaque signaling cannot turn an arbitrary cached
    // private attachment into a transferable resource even when its id/hash are known.
    if (!this.announced.has(offer.file_id)) return;
    const local = await this.readLocal(offer.file_id);
    if (!local) return;
    const digest = await sha256Hex(local.bytes, this.cryptoImpl);
    if (digest !== offer.sha256.toLowerCase()) return;

    const pc = this.rtcFactory!(this.rtcConfig);
    const session: ActiveRtc = {
      pc,
      remotePeerId,
      pendingIce: [],
      expiresAt: this.now() + this.requestTimeoutMs + 4_000,
    };
    this.active.set(sessionId, session);
    this.installIceRelay(sessionId, session);
    pc.addEventListener("datachannel", (event) => {
      void serveBlob(
        event.channel,
        offer.file_id,
        local,
        digest,
        this.chunkBytes,
      ).finally(() => {
        this.active.delete(sessionId);
        pc.close();
      });
    }, { once: true });
    try {
      await pc.setRemoteDescription(offer.sdp);
      await this.flushIce(session);
      const answer = await pc.createAnswer();
      await pc.setLocalDescription(answer);
      await this.signaling.signal(this.peerId, remotePeerId, sessionId, {
        type: "answer",
        sdp: pc.localDescription ?? answer,
      } satisfies SignalPayload);
    } catch (error) {
      this.active.delete(sessionId);
      pc.close();
      throw error;
    }
  }

  private async flushIce(session: ActiveRtc): Promise<void> {
    const queued = session.pendingIce.splice(0);
    for (const candidate of queued) await session.pc.addIceCandidate(candidate);
  }

  private pruneActive(): void {
    const now = this.now();
    for (const [id, session] of this.active) {
      if (session.expiresAt > now) continue;
      session.pc.close();
      this.active.delete(id);
    }
  }
}

function validLookup(value: PeerLookup): boolean {
  return Number.isSafeInteger(value.file_id) && value.file_id > 0 &&
    typeof value.sha256 === "string" && /^[a-f0-9]{64}$/i.test(value.sha256) &&
    typeof value.mime === "string" &&
    Number.isSafeInteger(value.size) && value.size >= 0 &&
    Array.isArray(value.providers) && value.providers.every((p) => typeof p === "string");
}

function parseSignalPayload(value: unknown): SignalPayload | null {
  if (!value || typeof value !== "object") return null;
  const raw = value as Record<string, unknown>;
  if (raw.type === "offer" && Number.isSafeInteger(raw.file_id) && Number(raw.file_id) > 0 &&
      typeof raw.sha256 === "string" && /^[a-f0-9]{64}$/i.test(raw.sha256) && isSessionDescription(raw.sdp)) {
    return { type: "offer", file_id: Number(raw.file_id), sha256: raw.sha256.toLowerCase(), sdp: raw.sdp };
  }
  if (raw.type === "answer" && isSessionDescription(raw.sdp)) return { type: "answer", sdp: raw.sdp };
  if (raw.type === "ice" && raw.candidate && typeof raw.candidate === "object") {
    return { type: "ice", candidate: raw.candidate as RTCIceCandidateInit };
  }
  if (raw.type === "cancel") return { type: "cancel" };
  return null;
}

function isSessionDescription(value: unknown): value is RTCSessionDescriptionInit {
  if (!value || typeof value !== "object") return false;
  const raw = value as Partial<RTCSessionDescriptionInit>;
  return typeof raw.type === "string" && typeof raw.sdp === "string";
}

async function serveBlob(
  channel: RTCDataChannel,
  fileId: number,
  blob: PeerLocalBlob,
  sha256: string,
  chunkBytes: number,
): Promise<void> {
  await channelOpen(channel);
  const meta: PeerMetaFrame = {
    type: "meta",
    file_id: fileId,
    sha256,
    mime: blob.mime,
    size: blob.bytes.byteLength,
  };
  channel.send(JSON.stringify(meta));
  for (let offset = 0; offset < blob.bytes.byteLength; offset += chunkBytes) {
    await waitForBackpressure(channel);
    const chunk = blob.bytes.slice(offset, Math.min(blob.bytes.byteLength, offset + chunkBytes));
    channel.send(chunk.buffer as ArrayBuffer);
  }
  channel.send(JSON.stringify({ type: "done" } satisfies PeerDoneFrame));
}

export function receiveVerifiedBlob(
  channel: RTCDataChannel,
  lookup: PeerLookup,
  cryptoImpl: Crypto = globalThis.crypto,
  signal?: AbortSignal,
): Promise<PeerFetchedBlob> {
  channel.binaryType = "arraybuffer";
  return new Promise((resolve, reject) => {
    let metaSeen = false;
    let done = false;
    let finishing = false;
    let total = 0;
    const chunks: Uint8Array[] = [];
    const cleanup = (): void => {
      channel.removeEventListener("message", onMessage);
      channel.removeEventListener("close", onClose);
      channel.removeEventListener("error", onError);
      signal?.removeEventListener("abort", onAbort);
    };
    const fail = (error: unknown): void => {
      if (done) return;
      done = true;
      cleanup();
      try { channel.close(); } catch { /* no-op */ }
      reject(error instanceof Error ? error : new Error(String(error)));
    };
    const finish = async (): Promise<void> => {
      if (done || finishing) return;
      finishing = true;
      try {
        if (!metaSeen || total !== lookup.size) throw new Error("peer payload size mismatch");
        const bytes = concatChunks(chunks, total);
        const digest = await sha256Hex(bytes, cryptoImpl);
        if (digest !== lookup.sha256.toLowerCase()) throw new Error("peer payload SHA-256 mismatch");
        done = true;
        cleanup();
        resolve({ fileId: lookup.file_id, bytes, mime: lookup.mime, sha256: digest });
      } catch (error) {
        finishing = false;
        fail(error);
      }
    };
    const onAbort = (): void => fail(signal?.reason ?? new DOMException("aborted", "AbortError"));
    const onClose = (): void => { if (!done) fail(new Error("peer channel closed before completion")); };
    const onError = (): void => fail(new Error("peer channel error"));
    const onMessage = (event: MessageEvent): void => {
      void (async () => {
        if (typeof event.data === "string") {
          const frame = JSON.parse(event.data) as Record<string, unknown>;
          if (frame.type === "meta") {
            if (metaSeen || frame.file_id !== lookup.file_id || typeof frame.sha256 !== "string" ||
                frame.sha256.toLowerCase() !== lookup.sha256.toLowerCase() || frame.mime !== lookup.mime ||
                frame.size !== lookup.size) throw new Error("peer metadata mismatch");
            metaSeen = true;
            return;
          }
          if (frame.type === "done") {
            await finish();
            return;
          }
          throw new Error("unknown peer control frame");
        }
        if (!metaSeen) throw new Error("peer chunk arrived before metadata");
        const bytes = event.data instanceof ArrayBuffer
          ? new Uint8Array(event.data)
          : event.data instanceof Blob
            ? new Uint8Array(await event.data.arrayBuffer())
            : null;
        if (!bytes) throw new Error("unsupported peer chunk type");
        total += bytes.byteLength;
        if (total > lookup.size) throw new Error("peer payload exceeds declared size");
        chunks.push(bytes.slice());
      })().catch(fail);
    };
    channel.addEventListener("message", onMessage);
    channel.addEventListener("close", onClose, { once: true });
    channel.addEventListener("error", onError, { once: true });
    signal?.addEventListener("abort", onAbort, { once: true });
    if (signal?.aborted) onAbort();
  });
}

async function channelOpen(channel: RTCDataChannel): Promise<void> {
  if (channel.readyState === "open") return;
  if (channel.readyState === "closing" || channel.readyState === "closed") throw new Error("peer channel unavailable");
  await new Promise<void>((resolve, reject) => {
    const done = (): void => {
      channel.removeEventListener("open", onOpen);
      channel.removeEventListener("close", onClose);
      channel.removeEventListener("error", onError);
    };
    const onOpen = (): void => { done(); resolve(); };
    const onClose = (): void => { done(); reject(new Error("peer channel closed")); };
    const onError = (): void => { done(); reject(new Error("peer channel error")); };
    channel.addEventListener("open", onOpen, { once: true });
    channel.addEventListener("close", onClose, { once: true });
    channel.addEventListener("error", onError, { once: true });
  });
}

async function waitForBackpressure(channel: RTCDataChannel): Promise<void> {
  if (channel.bufferedAmount <= MAX_BUFFERED_BYTES) return;
  channel.bufferedAmountLowThreshold = MAX_BUFFERED_BYTES / 2;
  await new Promise<void>((resolve, reject) => {
    const cleanup = (): void => {
      channel.removeEventListener("bufferedamountlow", onLow);
      channel.removeEventListener("close", onClose);
      channel.removeEventListener("error", onError);
    };
    const onLow = (): void => { cleanup(); resolve(); };
    const onClose = (): void => { cleanup(); reject(new Error("peer channel closed")); };
    const onError = (): void => { cleanup(); reject(new Error("peer channel error")); };
    channel.addEventListener("bufferedamountlow", onLow, { once: true });
    channel.addEventListener("close", onClose, { once: true });
    channel.addEventListener("error", onError, { once: true });
  });
}

function concatChunks(chunks: Uint8Array[], total: number): Uint8Array {
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return out;
}

export async function sha256Hex(bytes: Uint8Array, cryptoImpl: Crypto = globalThis.crypto): Promise<string> {
  const owned = bytes.slice().buffer as ArrayBuffer;
  const digest = new Uint8Array(await cryptoImpl.subtle.digest("SHA-256", owned));
  return [...digest].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

function withTimeout<T>(promise: Promise<T>, timeoutMs: number, signal?: AbortSignal): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => finish(() => reject(new Error("peer request timeout"))), timeoutMs);
    const onAbort = (): void => finish(() => reject(signal?.reason ?? new DOMException("aborted", "AbortError")));
    const finish = (action: () => void): void => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      signal?.removeEventListener("abort", onAbort);
      action();
    };
    signal?.addEventListener("abort", onAbort, { once: true });
    promise.then((value) => finish(() => resolve(value)), (error) => finish(() => reject(error)));
    if (signal?.aborted) onAbort();
  });
}
